from __future__ import annotations

import base64
import hashlib
import shutil
from datetime import datetime
from pathlib import Path

INSTALLER_VERSION = "3.6.0-BLIND-FAILURE-LEARNING-INSTALLER"
MODULE_NAME = "alliance_blind_failure_learning_v360.py"
REGISTRAR = "alliance_optional_property_modules.py"
MODULE_B64 = ''
REGISTRATION_BLOCK = '\n    # FOUNDATION 3.6 - blind failure learning + new frozen unseen exam\n    try:\n        if _route_exists(app, "/api/property-brain/mastery-v360/status"):\n            result["mastery_v360"] = {\n                "status": "ALREADY_REGISTERED",\n                "route": "/property-brain/mastery-v360",\n                "error": None,\n            }\n        else:\n            import alliance_blind_failure_learning_v360 as mastery_v360\n            mastery_result = mastery_v360.register(core)\n            result["mastery_v360"] = {**mastery_result, "error": None}\n    except Exception as exc:\n        result["mastery_v360"] = {\n            "status": "ERROR",\n            "error": f"{type(exc).__name__}: {exc}",\n            "route": "/property-brain/mastery-v360",\n            "fail_safe": True,\n        }\n'

PROTECTED_FILES = [
    'alliance_training_gate_finalizer_v350.py',
    'alliance_mastery_finalizer_v340.py',
    'alliance_ownership_mastery_blind_v330.py',
    'alliance_mastery_repair_v320.py',
    'alliance_expertise_bootcamp_v310.py',
    'alliance_property_brain_expertise_v300.py',
    'alliance_autonomous_gold_teacher_v294.py',
    'alliance_gold_v2_structural_lab_v293.py',
    'alliance_final_exam_v2922.py',
    'alliance_structural_integrity_v2921.py',
    'alliance_ownership_structural_v292.py',
    'alliance_infrastructure_curriculum_v291.py',
    'alliance_context_ownership_v25.py',
    'alliance_evidence_first_v24.py',
    'alliance_property_brain_gold_v2.py',
    'alliance_property_brain_foundation_v1.py',
]


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def syntax_check(path: Path) -> None:
    compile(path.read_text(encoding="utf-8"), str(path), "exec")


def main() -> int:
    root = Path.cwd()
    print(f"Alliance Foundation installer {INSTALLER_VERSION}")
    print(f"Repository: {root}")

    missing = [name for name in PROTECTED_FILES + [REGISTRAR] if not (root / name).exists()]
    if missing:
        raise SystemExit("Missing required baseline files: " + ", ".join(missing))

    required_markers = {
        "alliance_training_gate_finalizer_v350.py": "3.5.0-TRAINING-GATE-FINALIZER",
        "alliance_mastery_finalizer_v340.py": "3.4.0-MASTERY-FINALIZER-BLIND-AUDIT",
        "alliance_ownership_mastery_blind_v330.py": "3.3.0-OWNERSHIP-MASTERY-BLIND-SET",
        "alliance_mastery_repair_v320.py": "3.2.0-MASTERY-REPAIR",
        "alliance_gold_v2_structural_lab_v293.py": "2.9.3-GOLD-V2-STRUCTURAL-LAB",
    }
    for name, marker in required_markers.items():
        txt = (root / name).read_text(encoding="utf-8")
        if marker not in txt:
            raise SystemExit(f"Baseline verification failed: {name} missing {marker}")

    before = {name: sha256(root / name) for name in PROTECTED_FILES}
    registrar_path = root / REGISTRAR
    registrar_before = registrar_path.read_text(encoding="utf-8")
    if "alliance_training_gate_finalizer_v350" not in registrar_before:
        raise SystemExit("Registrar does not contain Foundation 3.5 registration. Refusing non-cumulative install.")

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = root / f"{REGISTRAR}.before-v360-{stamp}.bak"
    shutil.copy2(registrar_path, backup)
    print(f"Backup: {backup}")

    module_path = root / MODULE_NAME
    module_source = base64.b64decode(MODULE_B64).decode("utf-8")
    compile(module_source, MODULE_NAME, "exec")
    module_path.write_text(module_source, encoding="utf-8")

    registrar = registrar_before
    if "alliance_blind_failure_learning_v360" not in registrar:
        needle = "    return result"
        idx = registrar.rfind(needle)
        if idx < 0:
            raise SystemExit("Could not find final return result in registrar.")
        registrar = registrar[:idx] + REGISTRATION_BLOCK + "\n" + registrar[idx:]
        compile(registrar, REGISTRAR, "exec")
        registrar_path.write_text(registrar, encoding="utf-8")
    else:
        print("3.6 registrar block already present; leaving it unchanged.")

    syntax_check(module_path)
    syntax_check(registrar_path)
    for name in PROTECTED_FILES:
        syntax_check(root / name)

    after = {name: sha256(root / name) for name in PROTECTED_FILES}
    changed = [name for name in PROTECTED_FILES if before[name] != after[name]]
    if changed:
        shutil.copy2(backup, registrar_path)
        raise SystemExit("Regression protection failed; historical files changed: " + ", ".join(changed))

    final = registrar_path.read_text(encoding="utf-8")
    if "alliance_blind_failure_learning_v360" not in final or "/property-brain/mastery-v360" not in final:
        shutil.copy2(backup, registrar_path)
        raise SystemExit("3.6 registration verification failed; registrar restored.")

    print("PASS - Foundation 3.6 installed additively")
    print("PASS - 3.5 and all protected historical modules unchanged byte-for-byte")
    print("PASS - syntax validated in memory; no pycache written")
    print("Dashboard: /property-brain/mastery-v360")
    print("Safety: production writes 0, WhatsApp writes 0, Gold V1/V2 mutations 0")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
